import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 6 · Sealed-bid auction","description":"","frontmatter":{},"headers":[],"relativePath":"modules/06-sealed-bid-auction.md","filePath":"modules/06-sealed-bid-auction.md","lastUpdated":1790431304000}'),n={name:"modules/06-sealed-bid-auction.md"};function o(r,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="module-6-·-sealed-bid-auction" tabindex="-1">Module 6 · Sealed-bid auction <a class="header-anchor" href="#module-6-·-sealed-bid-auction" aria-label="Permalink to &quot;Module 6 · Sealed-bid auction&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>SealedAuction.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Market</td></tr><tr><td><strong>Pattern</strong></td><td>Commit–reveal</td></tr><tr><td><strong>Stamp</strong></td><td>Module 6</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>A sealed-bid auction means nobody sees anyone else&#39;s bid until bidding closes. That is the point: you bid what the item is worth to you, not one pound more than the person in front.</p><p>On a public chain, <strong>everything is visible</strong>. Contract storage is readable by anyone. Transaction data is readable before it is even mined, while it sits in the mempool. Writing <code>bid(100)</code> publishes your bid to the world, and on a public network a bot will outbid you in the same block for slightly more.</p><p>So a naive on-chain auction is not sealed, it is a live auction with extra steps.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>Bid in two phases.</p><p><strong>Commit.</strong> Send <code>keccak256(yourAddress, amount, salt)</code> — a fingerprint of your bid. It reveals nothing, and you cannot change it afterwards.</p><p><strong>Reveal.</strong> Send the amount and salt. The contract recomputes the hash and checks it matches what you committed. Now your bid counts, and now everyone can see it — but the commit phase is over, so nobody can react.</p><p>This is <strong>commit–reveal</strong>, and once you have seen it you will recognise it everywhere: sealed auctions, on-chain games, voting, randomness, domain registration.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Salt.</strong> A random value mixed into the hash. Without it, bids are guessable: there are only so many plausible amounts, and an attacker hashes them all until one matches. The salt makes the input space too large to search. Reuse a salt across auctions and you reintroduce the problem.</p><p><strong>Front-running.</strong> Seeing a pending transaction and getting yours in first. On a public chain this is an industry, not a hypothetical. DIDLab&#39;s four known validators make it far less pressing here — which is itself worth noticing, since it means this chain is a gentler teacher than reality.</p><p><strong>Pull payment.</strong> The contract does not send refunds; it records what it owes and lets people withdraw. This is the pattern that stops one bad recipient breaking everyone else.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>commit phase          reveal phase           after</span></span>
<span class="line"><span>──────────────  ▸  ──────────────────  ▸  ─────────</span></span>
<span class="line"><span>commitBid()        revealBid()             settle()</span></span>
<span class="line"><span>                                           withdrawRefund()</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>When</th></tr></thead><tbody><tr><td><code>createAuction(title, productId, commitSecs, revealSecs)</code></td><td>any resident</td><td>Sets both phases</td></tr><tr><td><code>commitBid(id, commitment)</code></td><td>anyone but the seller</td><td>Commit phase only, once</td></tr><tr><td><code>revealBid(id, amount, salt)</code></td><td>the committer</td><td>Reveal phase only</td></tr><tr><td><code>settle(id)</code></td><td>anyone</td><td>After the reveal phase</td></tr><tr><td><code>withdrawRefund()</code></td><td>any outbid bidder</td><td>Any time</td></tr><tr><td><code>hashBid(bidder, amount, salt)</code></td><td>view helper</td><td>Builds the commitment for you</td></tr></tbody></table><p>Phases are bounded: <code>MIN_PHASE</code> 30 seconds, <code>MAX_PHASE</code> 7 days.</p><p><strong>The commitment includes the bidder&#39;s address:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keccak256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">abi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">encodePacked</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, amount, salt))</span></span></code></pre></div><p>Without that, anyone could copy your commitment and submit it as their own. They would not know what it meant — but they would be committed to the identical bid, and could reveal it the moment you did. Binding the hash to the address makes a copied commitment unrevealable by anybody else.</p><p><strong>Tokens move at reveal, not commit.</strong> Committing is free, which is what keeps the commit phase cheap and private. At reveal the contract pulls the bid amount; a losing bid is immediately credited to <code>refunds</code> for later withdrawal, and an outbid leader&#39;s funds move to <code>refunds</code> when someone overtakes them.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>Withdrawals are pull, not push:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> withdrawRefund</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> owed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> refunds[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (owed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NothingToWithdraw</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    refunds[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// zero BEFORE transferring</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    token.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">safeTransfer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, owed);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The tempting alternative is to refund every loser inside <code>settle</code>. Then one recipient whose <code>transfer</code> reverts — a contract with no receive function, a token with a blocklist — takes the whole settlement down with it, permanently, for everybody.</p><p>Note also the ordering: the balance is zeroed <em>before</em> the transfer. If the transfer somehow re-entered <code>withdrawRefund</code>, the second call would find zero. Effects before interactions, every time.</p><p><strong>Committing and not revealing is free here.</strong> A bidder who commits a huge bid and never reveals costs themselves nothing and may deter others. Real designs require a deposit at commit time, forfeited if you fail to reveal. This contract does not — deliberately, so the gap is visible — and closing it is the first exercise.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Create an auction with short phases.</li><li>From a second account, call <code>hashBid(yourAddress, amount, salt)</code> to build a commitment, then <code>commitBid</code>. <strong>Write down the amount and salt</strong> — without both, you cannot reveal, and there is no recovery.</li><li>During the commit phase, look at the auction&#39;s storage on the explorer. Try to work out what anyone bid. You cannot.</li><li>Reveal from each bidder. Watch <code>BidRevealed</code> and which one is leading.</li><li>Settle. The seller is paid the high bid.</li><li>Losers call <code>withdrawRefund</code>.</li></ol><p>Then break it on purpose: commit a bid and never reveal. Note what it cost you.</p><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BidCommitted(id: 2, bidder: 0x…)                        // no amount anywhere</span></span>
<span class="line"><span>BidRevealed(id: 2, bidder: 0x…, amount: 40e18, leading: true)</span></span>
<span class="line"><span>Settled(id: 2, winner: 0x…, amount: 40e18)</span></span></code></pre></div><p>The commit event deliberately carries no amount. Everything a bidder needs to reveal is kept by the bidder, not the contract — which is why losing your salt is unrecoverable.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>For most auctions, obviously: eBay is cheaper, faster, understood by everybody, and can run a genuine sealed-bid process by simply not showing the bids.</p><p>Commit–reveal matters when <strong>the auctioneer is the party you cannot trust</strong> — when they might leak bids to a favoured buyer, insert a shill, or adjust the result. A database can do sealed bids; it cannot prove it did.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Non-revealers.</strong> Free to grief here.</li><li><strong>Timing analysis.</strong> Commit transactions are public. Who bid, and when, leaks even though amounts do not — and on a chain with few participants, that can be enough.</li><li><strong>Collusion.</strong> A bidding ring is invisible to the contract.</li><li><strong>The seller bidding via another address.</strong> Shill bidding needs identity to prevent, and identity does not exist here.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Omitting the address from the commitment.</strong> Commitments become copyable.</li><li><strong>Reusing a salt</strong>, or using a predictable one like <code>1</code>. Brute-forceable.</li><li><strong>Refunding in a loop.</strong> One reverting recipient freezes everyone.</li><li><strong>Losing the salt.</strong> Tell users loudly, at commit time, in the interface.</li><li><strong>Phases that are too short.</strong> Miss the reveal window and the bid is lost.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can a commitment be copied and submitted by someone else?</li><li>[ ] Can a bid be revealed after the reveal phase? Can it be revealed twice?</li><li>[ ] What does it cost to commit and never reveal?</li><li>[ ] Can <code>settle</code> be called twice? Before the reveal ends?</li><li>[ ] Can a refund be withdrawn twice, or re-entered?</li><li>[ ] Can the seller bid on their own auction?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Require a deposit at commit time, forfeited on a failed reveal. Decide where the forfeit goes, and what a malicious seller could do with that rule.</li><li>Make it a <strong>second-price</strong> (Vickrey) auction: the winner pays the second-highest bid. Work out what that changes about how people bid.</li><li>Add a reserve price the seller commits to at creation and reveals at settlement. Now the seller has a commitment to honour too.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://ethereum.org/en/developers/docs/smart-contracts/security/" target="_blank" rel="noreferrer">Commit–reveal schemes</a></li><li><em>Flash Boys 2.0</em> — the paper that named front-running on chain.</li><li>Vickrey auctions, and why theoretical elegance and practical use diverge.</li></ul><p><strong>Next:</strong> <a href="./07-verifiable-certificates">Module 7 · Verifiable certificates →</a></p>`,49)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
